class Solution:
    def maxEqualFreq(self, nums: List[int]) -> int:
        n = len(nums)
        for L in range(n, 1, -1):
            cnt = Counter(nums[:L])
            for v in list(cnt):
                cnt[v] -= 1
                if cnt[v] == 0:
                    del cnt[v]
                if len(set(cnt.values())) <= 1:
                    return L
                cnt[v] += 1
        return 1

