class Solution {
public:
    int maxEqualFreq(vector<int>& nums) {
        int n = nums.size();
        for (int L = n; L >= 2; --L) {
            unordered_map<int,int> cnt;
            for (int i = 0; i < L; ++i) cnt[nums[i]]++;
            for (auto& [v, c] : cnt) {
                cnt[v]--;
                unordered_set<int> s;
                bool ok = true;
                for (auto& [_, x] : cnt) if (x > 0) s.insert(x);
                ok = s.size() <= 1;
                cnt[v]++;
                if (ok) return L;
            }
        }
        return 1;
    }
};

