class Solution {
    public int maxEqualFreq(int[] nums) {
        int n = nums.length;
        for (int L = n; L >= 2; L--) {
            Map<Integer,Integer> cnt = new HashMap<>();
            for (int i = 0; i < L; i++) cnt.merge(nums[i], 1, Integer::sum);
            for (int v : new ArrayList<>(cnt.keySet())) {
                cnt.merge(v, -1, Integer::sum);
                Set<Integer> s = new HashSet<>();
                for (int x : cnt.values()) if (x > 0) s.add(x);
                cnt.merge(v, 1, Integer::sum);
                if (s.size() <= 1) return L;
            }
        }
        return 1;
    }
}

