class Solution {
public:
    int maxEqualFreq(vector<int>& nums) {
        unordered_map<int,int> cnt, freq;
        int maxF = 0, d = 0, ans = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            int x = nums[i];
            if (cnt[x] > 0) freq[cnt[x]]--; else d++;
            cnt[x]++;
            freq[cnt[x]]++;
            maxF = max(maxF, cnt[x]);
            if (maxF == 1 ||
                (freq[1] == 1 && freq[maxF] == d - 1) ||
                (freq[maxF] == 1 && freq[maxF - 1] == d - 1))
                ans = i + 1;
        }
        return ans;
    }
};

