class Solution {
    public int maxEqualFreq(int[] nums) {
        Map<Integer,Integer> cnt = new HashMap<>(), freq = new HashMap<>();
        int maxF = 0, d = 0, ans = 0;
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            int c = cnt.getOrDefault(x, 0);
            if (c > 0) freq.merge(c, -1, Integer::sum); else d++;
            cnt.put(x, c + 1);
            freq.merge(c + 1, 1, Integer::sum);
            maxF = Math.max(maxF, c + 1);
            Integer f1 = freq.get(1), fMax = freq.get(maxF), fPrev = freq.get(maxF - 1);
            if (maxF == 1 ||
                (f1 != null && f1 == 1 && fMax != null && fMax == d - 1) ||
                (fMax != null && fMax == 1 && fPrev != null && fPrev == d - 1))
                ans = i + 1;
        }
        return ans;
    }
}

